head.script:
// 상장관련공통함수
scwin.gDepCd = js_dep_cd;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.setCode();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35613.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts1_OnLoadCompleted
 * @description dts1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts1_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35613.dts1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts1_OnLoadError
 * @description dts1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35613.dts1_OnLoadError" });
    }
};

/**
 * @method
 * @name cmb_dep_cd_onselchange
 * @description cmb_dep_cd onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_dep_cd_onselchange = function() {
    try {
        scwin.gDepCd = $c.cp.valueOfIndex(cmb_dep_cd, "VALUE", cmb_dep_cd.getSelectedIndex());
        dts_EmpNo.UseFilter = true;
        dts_EmpNo.Filter();
        cmb_emp_no.ComboDataID = "dts_EmpNo";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35613.cmb_dep_cd_onselchange" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35613.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onblur
 * @description txb_ISU_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onblur = function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            txb_ISU_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35613.txb_ISU_CD_onblur" });
    }
};

/**
 * @method
 * @name img_ISU_NM_onclick
 * @description img_ISU_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISU_NM_onclick = function() {
    try {
        $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST, js_market, "A");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35613.img_ISU_NM_onclick" });
    }
};

/**
 * @method
 * @name dts_EmpNo_OnFilter
 * @description Emp No On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.dts_EmpNo_OnFilter = function(row) {
    try {
        //  부서코드에  해당하는 사원을 가져온다.
        if (scwin.gDepCd === "%") {
            // 전체일 경우 모두 보여준다.
            return true;
        } else {
            // alert(dts_EmpNo.NameValue(row, "DEP_CD") );
            if (dts_EmpNo.getCellData(row, "DEP_CD") === scwin.gDepCd ||
                dts_EmpNo.getCellData(row, "DEP_CD") === "") {
                return true;
            } else {
                return false;
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35613.dts_EmpNo_OnFilter" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀 다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.data.downloadGridViewExcel(grd_corp_dtl, {fileName: "종류주식-주주수 요건", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35613.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35613.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_DepCd",
        action : "/AdminAndDlstedDetection.do",
        ref : "",
        target : "dts_DepCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    const sbmOptions2 = {
        id : "sbm_dts_EmpNo",
        action : "/AdminAndDlstedDetection.do",
        ref : "",
        target : "dts_EmpNo=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description 종류주식 주주수요건 검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const isu_cd = txb_ISU_CD.getValue();
    const team_cd = $c.cp.valueOfIndex(cmb_dep_cd, "VALUE", cmb_dep_cd.getSelectedIndex());
    const charge_id = $c.cp.valueOfIndex(cmb_emp_no, "VALUE", cmb_emp_no.getSelectedIndex());
    const sbmOptions = {
        id : "sbm_dts1",
        action : "/AdminAndDlstedDetection.do",
        ref : "",
        target : "dts1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};
